/* Event Registration Form Styles */
.event-registration-form {
  max-width: 500px;
  margin: 2rem 0;
  padding: 1.5rem;
  background: white;
  border: 2px solid var\(--color-border-rough, #2A5CA6\);
  border-radius: 8px;
  box-shadow: 3px 3px 0 var\(--color-border-rough, #2A5CA6\);
}

.spots-indicator {
  margin-bottom: 1rem;
  font-weight: 600;
}

.spots-available {
  color: #4CAF50;
}

.spots-full {
  color: #F4A261;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  margin-bottom: 0.5rem;
  font-family: var\(--font-heading, sans-serif\);
  font-weight: 600;
  color: var\(--color-primary, #2A5CA6\);
}

.form-group input[type="email"],
.form-group input[type="text"],
.form-group textarea {
  width: 100%;
  padding: 0.75rem;
  border: 2px solid var\(--color-border-rough, #2A5CA6\);
  border-radius: 4px;
  font-family: var\(--font-body, sans-serif\);
  font-size: 1rem;
  transition: border-color 0.2s ease;
}

.form-group input:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var\(--color-accent, #F4A261\);
}

.form-group.checkbox label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
  font-weight: normal;
}

.form-group.checkbox input[type="checkbox"] {
  width: auto;
  cursor: pointer;
}

.submit-btn {
  width: 100%;
  padding: 0.875rem;
  background: var\(--color-primary, #2A5CA6\);
  color: white;
  font-family: var\(--font-heading, sans-serif\);
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid var\(--color-border-rough, #2A5CA6\);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.submit-btn:hover:not\(:disabled\) {
  background: var\(--color-accent, #F4A261\);
  transform: translate\(-1px, -1px\);
  box-shadow: 2px 2px 0 var\(--color-border-rough, #2A5CA6\);
}

.submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error-message {
  padding: 0.75rem;
  margin-bottom: 1rem;
  background: #ffebee;
  color: #d32f2f;
  border-radius: 4px;
  border-left: 4px solid #d32f2f;
}

.rsvp-success {
  padding: 2rem;
  background: #e8f5e9;
  border: 2px solid #4CAF50;
  border-radius: 8px;
  text-align: center;
}

.rsvp-success h3 {
  color: #2e7d32;
  margin-bottom: 0.5rem;
}

.rsvp-closed {
  padding: 1.5rem;
  background: #fff3e0;
  border: 2px solid #F4A261;
  border-radius: 8px;
  text-align: center;
  color: #e65100;
}

/* Responsive */
@media \(max-width: 768px\) {
  .event-registration-form {
    padding: 1rem;
    margin: 1rem 0;
  }
}
